#!/usr/bin/env python3
"""Generate Soong/Make glue for the stock files listed in proprietary-files.txt.

    setup_makefiles.py <vendor_dir>

Reads  <vendor_dir>/proprietary-files.txt
Writes <vendor_dir>/Android.bp              prebuilt modules (apps, jars, native libs, symlinks)
       <vendor_dir>/vantage-vendor.mk       PRODUCT_PACKAGES / PRODUCT_COPY_FILES

Only module definitions are generated; the binaries stay under <vendor_dir>/proprietary/,
which is populated by scripts/extract-firmware.sh and is never committed.
"""
import re
import sys
from pathlib import Path

OWNER = "motorola"
PART_FLAG = {"system_ext": "system_ext_specific: true,", "product": "product_specific: true,", "system": ""}
COPY_OUT = {"system": "$(TARGET_COPY_OUT_SYSTEM)", "system_ext": "$(TARGET_COPY_OUT_SYSTEM_EXT)",
            "product": "$(TARGET_COPY_OUT_PRODUCT)"}
HEADER = "// Generated by scripts/setup_makefiles.py from proprietary-files.txt. Do not edit.\n"


def parse_manifest(path):
    for raw in path.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        spec, _, sha = line.partition("|")
        rel, *flags = spec.split(";")
        yield rel, flags, sha


def module_name(stem, taken):
    name = re.sub(r"[^A-Za-z0-9_.+@-]", "_", stem)
    while name in taken:
        name += "_vantage"
    taken.add(name)
    return name


def main():
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    vdir = Path(sys.argv[1])
    bp, packages, copies, taken = [HEADER], [], [], set()
    bp.append('soong_namespace {\n}\n')
    done = set()
    for rel, flags, _ in parse_manifest(vdir / "proprietary-files.txt"):
        if rel in done:  # a file may be required by more than one component
            continue
        done.add(rel)
        part, _, sub = rel.partition("/")
        flag = PART_FLAG.get(part)
        if flag is None:
            sys.exit(f"unsupported partition in manifest: {rel}")
        indent = f"    {flag}\n" if flag else ""
        src = f"proprietary/{rel}"
        fname = rel.rsplit("/", 1)[-1]
        symlink = next((f.split("=", 1)[1] for f in flags if f.startswith("SYMLINK=")), None)
        if symlink:
            name = module_name("symlink_" + sub.replace("/", "_"), taken)
            bp.append(
                f'install_symlink {{\n    name: "{name}",\n{indent}'
                f'    installed_location: "{sub}",\n    symlink_target: "{symlink}",\n}}\n'
            )
            packages.append(name)
        elif fname.endswith(".apk"):
            name = module_name(fname[:-4], taken)
            if "PRESIGNED" in flags:
                sign = "    presigned: true,\n    preprocessed: true,\n"
            else:
                cert = next((f.split("=", 1)[1] for f in flags if f.startswith("CERT=")), "platform")
                sign = f'    certificate: "{cert}",\n'
            priv = "    privileged: true,\n" if "PRIV" in flags else ""
            bp.append(
                f'android_app_import {{\n    name: "{name}",\n    owner: "{OWNER}",\n    apk: "{src}",\n'
                f'{sign}{priv}{indent}    dex_preopt: {{\n        enabled: false,\n    }},\n}}\n'
            )
            packages.append(name)
        elif fname.endswith(".jar"):
            name = module_name(fname[:-4], taken)
            bp.append(
                f'dex_import {{\n    name: "{name}",\n    owner: "{OWNER}",\n    jars: ["{src}"],\n{indent}}}\n'
            )
            packages.append(name)
        elif fname.endswith(".so") and "/lib64/" in f"/{sub}":
            name = module_name(fname[:-3], taken)
            bp.append(
                f'cc_prebuilt_library_shared {{\n    name: "{name}",\n    owner: "{OWNER}",\n'
                f'    stem: "{fname[:-3]}",\n    compile_multilib: "64",\n{indent}'
                f'    srcs: ["{src}"],\n    strip: {{\n        none: true,\n    }},\n'
                f'    check_elf_files: false,\n    prefer: true,\n}}\n'
            )
            packages.append(name)
        else:
            copies.append(f"vendor/motorola/vantage/{src}:{COPY_OUT[part]}/{sub}")
    (vdir / "Android.bp").write_text("\n".join(bp), encoding="utf-8", newline="\n")

    mk = ["# Generated by scripts/setup_makefiles.py from proprietary-files.txt. Do not edit.", "",
          "PRODUCT_SOONG_NAMESPACES += vendor/motorola/vantage", ""]
    if packages:
        mk.append("PRODUCT_PACKAGES += \\")
        mk += [f"    {p} \\" for p in packages[:-1]] + [f"    {packages[-1]}", ""]
    if copies:
        mk.append("PRODUCT_COPY_FILES += \\")
        mk += [f"    {c} \\" for c in copies[:-1]] + [f"    {copies[-1]}", ""]
    (vdir / "vantage-vendor.mk").write_text("\n".join(mk), encoding="utf-8", newline="\n")
    print(f"{len(packages)} modules, {len(copies)} copied files")
    return 0


if __name__ == "__main__":
    sys.exit(main())
